#!/bin/sh
# Runs inside the `client` container of compose.cluster.yml.
#
# 1. Independent Asir jobs succeed with verified results on at least two workers.
# 2. The same factorization through the asir, macaulay2 and oscar backends gives
#    the same typed result, and every worker reports its CAS version.
# 3. The GKZ system of design §9.2 is generated by Macaulay2 and passes the
#    mathematical checks.
set -eu

expect_workers="${EXPECT_WORKERS:-4}"
jobs="${JOBS:-8}"

fail() { echo "FAIL: $*" >&2; exit 1; }

i=0
until [ "$(algebramesh workers | grep -c '"online": true')" -ge "$expect_workers" ]; do
    i=$((i + 1))
    [ "$i" -le 90 ] || { algebramesh workers >&2; fail "workers did not come online"; }
    sleep 1
done
echo "online workers: $expect_workers"

# Prints the record of a job, failing unless it SUCCEEDED.
wait_ok() {
    record=$(algebramesh wait "$1" --timeout 600) || { echo "$record" >&2; fail "job $1"; }
    printf '%s\n' "$record" | grep -q '^  "state": "SUCCEEDED"' || { echo "$record" >&2; fail "job $1 did not succeed"; }
    printf '%s\n' "$record"
}

# --- 1. distribution over the Asir workers --------------------------------------
ids=""
n=0
while [ "$n" -lt "$jobs" ]; do
    case $((n % 3)) in
        0) job=examples/factor.json ;;
        1) job=examples/factor_rational.json ;;
        *) job=tests/fixtures/factor_x40_minus_y40.json ;;
    esac
    ids="$ids $(algebramesh submit "$job")"
    n=$((n + 1))
done
agents=""
for id in $ids; do
    record=$(wait_ok "$id")
    printf '%s\n' "$record" | grep -q '"verified_product": true' || fail "unverified result for $id"
    agent=$(printf '%s\n' "$record" | sed -n 's/^  "agent_id": "\(.*\)",*$/\1/p')
    host=$(printf '%s\n' "$record" | sed -n 's/.*"executed by agent \([^ ]*\) on .*/\1/p')
    echo "$id SUCCEEDED on $host"
    agents="$agents
$agent"
done
distinct=$(printf '%s\n' "$agents" | sed '/^$/d' | sort -u | wc -l)
echo "distinct asir agents: $distinct"
[ "$distinct" -ge 2 ] || fail "expected jobs on at least two agents"

# --- 2. asir and macaulay2 through the same API -----------------------------------
summary() {
    printf '%s\n' "$1" | grep -E '"(constant|display|multiplicity)"' | sed 's/,$//' | sort
}
asir=$(wait_ok "$(algebramesh submit examples/factor.json)")
m2=$(wait_ok "$(algebramesh submit examples/factor_macaulay2.json)")
printf '%s\n' "$m2" | grep -q '"name": "macaulay2"' || fail "macaulay2 job ran elsewhere"
printf '%s\n' "$m2" | grep -q '"verified_product": true' || fail "unverified macaulay2 result"
if [ "$(summary "$asir")" != "$(summary "$m2")" ]; then
    echo "asir:"; summary "$asir"; echo "macaulay2:"; summary "$m2"
    fail "asir and macaulay2 factorizations differ"
fi
oscar=$(wait_ok "$(algebramesh submit examples/factor_oscar.json)")
printf '%s
' "$oscar" | grep -q '"name": "oscar"' || fail "oscar job ran elsewhere"
if [ "$(summary "$asir")" != "$(summary "$oscar")" ]; then
    echo "asir:"; summary "$asir"; echo "oscar:"; summary "$oscar"
    fail "asir and oscar factorizations differ"
fi
echo "asir, macaulay2 and oscar give the same factorization:"
summary "$m2" | grep display
workers=$(algebramesh workers)
for v in '"backend_version": "Macaulay2 1.24.11' '"backend_version": "OSCAR 1.8.2' '"backend_version": "20260331"'; do
    printf '%s
' "$workers" | grep -q "$v" || { echo "$workers" >&2; fail "missing $v"; }
done
backends=$(algebramesh backends)
for b in '"name": "asir"' '"name": "macaulay2"' '"name": "oscar"' '"gkz.generate"'; do
    printf '%s
' "$backends" | grep -q "$b" || { echo "$backends" >&2; fail "missing $b in backends"; }
done
echo "workers report versions and capabilities"

# --- 3. GKZ system of design §9.2 -----------------------------------------------------
gkz=$(wait_ok "$(algebramesh submit examples/gkz_design_9_2.json)")
for check in euler_operators_match toric_binomials_valid generated_by_toric_and_euler; do
    printf '%s\n' "$gkz" | grep -q "\"$check\": true" || { echo "$gkz" >&2; fail "GKZ check $check"; }
done
[ "$(printf '%s\n' "$gkz" | grep -c '"in_ideal": true')" -eq 3 ] || { echo "$gkz" >&2; fail "expected generators not all in the ideal"; }
echo "GKZ(A=[[1,1,1],[0,1,2]], beta=[3,4]) generators:"
printf '%s\n' "$gkz" | sed -n '/"generators"/,/"toric_generators"/p' | grep '"display"'
echo "all cluster checks passed"
